create database Customer_behaviour; 
use Customer_behaviour;
select * from customer_shopping_behavior limit 20;

#Q1 what istotal revenue generated by male vs female customers?
select gender, sum(purchase_amount)as revenue
from customer_shopping_behavior
group by gender;

select * from  customer_shopping_behavior;
#Q2 which customer used a discount but still spent more than the average purchaseamount
select customer_id, purchase_amount
from customer_shopping_behavior
where discount_applied = 'yes'
and purchase_amount >= (select avg(purchase_amount )from customer_shopping_behavior);
select * from customer_shopping_behavior;

#Q3 which are the top 5 products with highest average review rating 
select item_purchased, round(avg(review_rating),2) as "Average product rating"
from customer_shopping_behavior
group by item_purchased
order by avg(review_rating) desc limit 5;

select * from customer_shopping_behavior;

#Q4 compare the average purchase ammounts between standard & express shipping
select shipping_type,
round(avg(purchase_amount),2) as "average purchase"
from customer_shopping_behavior
where shipping_type in ('Standard','Express')
group by shipping_type;

#Q5 do subscriber customer spen more ?comapare average spend and total revenue between subscribers and non subscribers
select subscription_status,
count(customer_id)as "total customers",
round(avg(purchase_amount), 2) as avg_spend,
round(sum(purchase_amount), 2) as total_revenue
from customer_shopping_behavior
group by subscription_status
order by avg_spend,total_revenue desc;

select * from customer_shopping_behavior;
#Q6 which 5 products have the highest percentage of purchase with discouts applied
select item_purchased,
round(100 * sum(case when discount_applied = 'yes' then 1 else 0 end)/count(*),2)as discount_rate 
from customer_shopping_behavior
group by item_purchased 
order by discount_rate desc limit 5;

#Q7 segment customers into new, returning and loyal based on their total
#number of previous purchases, and show count of each segment 
with customer_type as(
select customer_id,
previous_purchases,
case
      when previous_purchases = 1 then 'New'
      when previous_purchases between 2 and 10 then 'Returning'
      else 'Loyal'
      end as customer_segment
from customer_shopping_behavior
)

select customer_segment, count(*) as "Number of customers"
from customer_type
group by customer_segment;

